import dataclasses
import inspect
from collections.abc import AsyncGenerator
from typing import Any, Literal

import httpx
from pydantic import BaseModel

from snowfall.vendor.junction_one import errors
from snowfall.vendor.junction_one.models import autogenerated as auto_models
from snowfall.vendor.junction_one.models import base as models
from snowfall.vendor.rate_limiter.client import Client as RateLimitClient

_Method = Literal["GET", "POST"]


@dataclasses.dataclass(frozen=True)
class JunctionOneAuth(object):
    authorization: str
    api_key: str


class TokenAuth(httpx.Auth):
    def __init__(self, auth: JunctionOneAuth):
        self._auth = auth

    async def async_auth_flow(
        self,
        request: httpx.Request,
    ) -> AsyncGenerator[httpx.Request, httpx.Response]:
        request.headers.update({
            "X-Api-Key": self._auth.api_key,
            "Authorization": self._auth.authorization,
        })
        yield request


class JunctionOneClient(object):
    def __init__(
        self,
        api_base_url: str,
        http_client: httpx.AsyncClient,
        auth: httpx.Auth | None = None,
        rate_limit_client: RateLimitClient | None = None,
        timeout: float = 60.0,
    ) -> None:
        self._api_base_url = httpx.URL(api_base_url)
        self._http_client = http_client
        self._rate_limit_client = rate_limit_client
        self.timeout = timeout

        self._http_client.headers.update({"Accept": "application/json"})

        if auth:
            self._http_client.auth = auth

    async def create_trip(
        self,
        query: models.TripCreateRequest,
        rate_limit_timeout: float | None = None,
    ) -> auto_models.Trip:
        response = await self._make_request(
            "POST",
            "/v1/trip/create",
            query,
            rate_limit_timeout=rate_limit_timeout,
        )

        if not response.data:
            raise errors.EmptyDataError()

        ret_model = auto_models.GetTripBoardsResponse(**response.data)

        if not ret_model.trip:
            raise ValueError("missing trip")

        return ret_model.trip

    async def list_trips(
        self,
        query: models.TripListRequest,
        rate_limit_timeout: float | None = None,
    ) -> list[auto_models.Trip]:
        response = await self._make_request(
            "GET",
            "/v1/trip/list",
            query,
            rate_limit_timeout=rate_limit_timeout,
        )

        if not response.data:
            raise errors.EmptyDataError()

        ret_model = auto_models.ListTripsResponse(**response.data)

        if not ret_model.trips:
            raise ValueError("missing trips")

        return ret_model.trips

    async def delete_trip(
        self,
        query: models.TripDeleteRequest,
        rate_limit_timeout: float | None = None,
    ) -> bool:
        await self._make_request(
            "GET",
            "/v1/trip/delete",
            query,
            rate_limit_timeout=rate_limit_timeout,
        )
        return True

